script:
(function () {
  'use strict';
  // 401(k) save the max: spread the room left under the 2026 limit evenly over the paychecks left.
  //   limit      = deferral limit + catch-up for age at year-end (0 / $8,000 at 50+ / $11,250 at 60-63)
  //   room       = max(0, limit - contributed so far - deferrals to another employer's plan)
  //   per check  = room / paychecks left;  percent = per check / (salary / paychecks per year)
  //   whole %    = floor of the exact percent (the highest whole percent that stays under the limit)
  // Checked in Node (scratch tests): age 45, $90,000 biweekly, $12,000 so far, 8 checks left ->
  //   $12,500 room, $1,562.50 a check, 45.14% of $3,461.54 gross; age 55 -> $20,500 room,
  //   $2,562.50 = 74.03%; age 61 -> $23,750 room; age 64 -> back to $8,000 catch-up; $40,000 so far
  //   -> already over the limit. Current 10% for 8 checks -> $12,000 + $2,769.23 = $14,769.23.
  // ---- 2026 IRS limits (IRS Notice 2025-67, tax year 2026) ----------------------
  var LIMITS = {
    year: 2026,
    deferral: 24500,        // 402(g) elective deferral limit (employee pre-tax + Roth)
    catchUp50: 8000,        // catch-up, age 50 or older by year-end
    catchUp60to63: 11250,   // SECURE 2.0 higher catch-up, ages 60-63 (replaces the age-50 amount)
    rothCatchUpWages: 150000 // 414(v)(7): prior-year FICA wages above this -> catch-up must be Roth
  };
  // --------------------------------------------------------------------------------

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function catchUpFor(age) {
    if (age >= 60 && age <= 63) return LIMITS.catchUp60to63;
    if (age >= 50) return LIMITS.catchUp50;
    return 0;
  }

  function plan(p) {
    var catchUp = p.allowCatchUp ? catchUpFor(p.age) : 0;
    var limit = LIMITS.deferral + catchUp;
    var used = p.toDate + p.otherPlan;
    var room = Math.max(0, limit - used);
    var gross = p.salary / p.periods;
    var perCheck = room / p.left;
    var pct = gross > 0 ? perCheck / gross * 100 : Infinity;
    var pace = used + gross * p.current / 100 * p.left;
    return { catchUp: catchUp, limit: limit, used: used, over: Math.max(0, used - limit), room: room,
             gross: gross, perCheck: perCheck, pct: pct, pace: pace };
  }

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }

  function update() {
    var p = {
      age: Math.round(num('smAge')), salary: num('smSalary'), periods: parseInt(document.getElementById('smFreq').value, 10),
      toDate: num('smToDate'), left: Math.round(num('smLeft')), current: num('smCurrent'),
      otherPlan: num('smOtherPlan'), allowCatchUp: document.getElementById('smCatchUp').checked
    };
    if (isNaN(p.current)) p.current = 0;
    if (isNaN(p.otherPlan)) p.otherPlan = 0;
    var error = document.getElementById('smError');
    var bad = [p.age, p.salary, p.toDate, p.left].some(function (v) { return !isFinite(v); }) ||
              p.age < 16 || p.age > 99 || p.salary < 0 || p.toDate < 0 || p.otherPlan < 0 ||
              p.left < 1 || p.left > p.periods || p.current < 0 || p.current > 100;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter an age from 16 to 99, non-negative amounts, a contribution rate from 0 to 100% ' +
                          'and from 1 to ' + p.periods + ' paychecks left.';
      return;
    }
    var r = plan(p);
    set('smBase', whole.format(LIMITS.deferral));
    set('smCatch', whole.format(r.catchUp));
    set('smLimit', whole.format(r.limit));
    set('smGross', money.format(r.gross));
    set('smRemaining', money.format(r.room));
    set('smPerCheck', money.format(r.perCheck));
    set('smPct', isFinite(r.pct) ? r.pct.toFixed(2) + '%' : '–');
    set('smPace', money.format(r.pace));

    var note = document.getElementById('smNote'), msg = '';
    if (r.over > 0) {
      msg = 'You are already ' + money.format(r.over) + ' over your ' + LIMITS.year + ' limit. Stop contributing and ask ' +
            'your plan to refund the excess before April 15 of next year, or it is taxed twice.';
    } else if (r.room === 0) {
      msg = 'You have already reached your ' + LIMITS.year + ' limit, so you can set your contribution to 0% for the rest of the year.';
    } else if (r.pct > 100) {
      msg = 'Your remaining paychecks are too small to reach the limit: you would need ' + money.format(r.perCheck) +
            ' from each, more than your gross pay. The most you could add is about ' + money.format(r.gross * p.left) +
            ' before taxes and other deductions.';
    } else if (r.pace > r.limit + 0.005) {
      msg = 'At your current ' + p.current + '% you would reach the limit early; most plans stop deductions there, ' +
            'which can mean missing employer match on later paychecks.';
    }
    note.textContent = msg;
    note.hidden = msg === '';

    var floorPct = isFinite(r.pct) ? Math.floor(r.pct + 1e-9) : 0;
    set('smSummary', r.room > 0 && r.pct <= 100
      ? 'If your plan only takes whole percents, ' + floorPct + '% keeps you under the limit (about ' +
        money.format(r.gross * floorPct / 100) + ' a paycheck) and ' + (floorPct + 1) + '% reaches it a little early.'
      : '');

    var rows = [], ytd = r.used, per = r.pct > 100 ? r.gross : r.perCheck;
    for (var i = 1; i <= p.left; i++) {
      var c = r.room > 0 ? Math.min(per, Math.max(0, r.limit - ytd)) : 0;
      ytd += c;
      rows.push('<tr><td>' + i + '</td><td>' + money.format(c) + '</td><td>' + money.format(ytd) + '</td><td>' +
                money.format(Math.max(0, r.limit - ytd)) + '</td></tr>');
    }
    document.getElementById('smSchedule').innerHTML = rows.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('smForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
